import path from 'node:path';
import fs from 'node:fs';

const DATA_DIR = path.resolve('data');

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description:
        'Return metadata (relative path, byte size, lowercase extension) for a file under the data directory. Does not expose file contents.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Relative path of the file within the data directory.'
          }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (typeof args !== 'object' || args === null) {
    throw new Error('Invalid arguments');
  }

  for (const key of Object.keys(args)) {
    if (key !== 'path') {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  const { path: relPath } = args;
  if (typeof relPath !== 'string' || relPath.length === 0) {
    throw new Error('path is required and must be a non-empty string');
  }

  // Reject absolute paths early.
  if (path.isAbsolute(relPath)) {
    throw new Error('path must be relative to the data directory');
  }

  // Reject any parent-directory reference (traversal), even if it would
  // lexically resolve back inside the data directory.
  if (relPath.split(/[\\/]/).some((seg) => seg === '..')) {
    throw new Error('path must not contain parent directory references');
  }

  // Resolve and ensure the result stays within the data directory.
  const resolved = path.resolve(DATA_DIR, relPath);
  const rel = path.relative(DATA_DIR, resolved);
  if (
    rel === '..' ||
    rel.startsWith('..' + path.sep) ||
    path.isAbsolute(rel)
  ) {
    throw new Error('path is outside the data directory');
  }

  let stat;
  try {
    stat = await fs.promises.stat(resolved);
  } catch (err) {
    throw new Error(`File not found: ${relPath}`);
  }

  if (!stat.isFile()) {
    throw new Error(`Not a file: ${relPath}`);
  }

  const ext = path.extname(rel).toLowerCase();
  const text = `path: ${rel}\nsize: ${stat.size}\nextension: ${ext}`;

  return {
    content: [{ type: 'text', text }]
  };
}

